def three_sum(nums):
    found = set()
    for a, b, c in itertools.combinations(nums, 3):
        if a + b + c == 0:
            found.add(tuple(sorted((a, b, c))))
    return [list(t) for t in found]

def three_sum(nums):
    found = set()
    for i in range(len(nums)):
        seen = set()
        for x in nums[i + 1:]:
            if -nums[i] - x in seen:
                found.add(tuple(sorted((nums[i], x, -nums[i] - x))))
            seen.add(x)
    return [list(t) for t in found]

def three_sum(nums):
    nums, out = sorted(nums), []
    for i in range(len(nums) - 2):
        if nums[i] > 0:
            break
        if i and nums[i] == nums[i - 1]:
            continue                            # same first number: same triplets
        lo, hi = i + 1, len(nums) - 1
        while lo < hi:
            s = nums[i] + nums[lo] + nums[hi]
            if s < 0:
                lo += 1
            elif s > 0:
                hi -= 1
            else:
                out.append([nums[i], nums[lo], nums[hi]])
                lo, hi = lo + 1, hi - 1
                while lo < hi and nums[lo] == nums[lo - 1]:
                    lo += 1                     # skip equal second numbers
    return out
